examples.template:
HStack {
    MonarchButton({{title}}) { showsAssistant = true }
    Text({{hint}})
        .monarchTextStyle(.body)
}
    .monarchAiAssistantPanel(isPresented: $showsAssistant) {
        MonarchAiAssistantPanel(
            {{title}},
            conversation: conversation,
            isPresented: $showsAssistant,
            prompt: $draft,
            context: [
                MonarchAiContextItem(id: "page", kind: .page, label: {{context.0.items}}, group: {{context.0.label}}),
                MonarchAiContextItem(id: "selection", kind: .selection, label: {{context.1.items}}, group: {{context.1.label}}),
            ],
            starters: [
                MonarchAiStarterPrompt(id: "sum", title: {{starters.0}}, prompt: {{starters.0}}),
                MonarchAiStarterPrompt(id: "week", title: {{starters.1}}, prompt: {{starters.1}}),
                MonarchAiStarterPrompt(id: "status", title: {{starters.2}}, prompt: {{starters.2}}),
            ]
        )
    }

examples.setupTemplate:
private struct EchoTransport: MonarchAiTransport {
    func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
        MonarchAiEventStream { continuation in
            continuation.yield(.textDelta("You asked: " + (request.messages.last?.text ?? "")))
            continuation.yield(.done())
            continuation.finish()
        }
    }
}

// Hold the conversation above the navigation so it survives moving between screens.
@State private var conversation = MonarchAiConversation(transport: EchoTransport())
@State private var showsAssistant = false
@State private var draft = ""

